    { term: "Agroforestry", def: "Combining trees with crop or livestock farming, one component of the Green Legacy movement." },
    { term: "Climate-smart agriculture", def: "Farming intensified to increase productivity while coping with climate pressures, a goal of the movement." },
    { term: "CRGE Strategy", def: "The Climate Resilient Green Economy Strategy guiding Ethiopia's efforts on the ground." },
    { term: "Post-planting care", def: "Watering, weeding and replacement planting done to raise the survival rate of planted seedlings." },
    { term: "Paris Climate Change Agreement", def: "The international climate commitment that the movement helps Ethiopia meet." },
    { term: "Desertification", def: "The spread of desert-like conditions, which the movement battles along with soil erosion." }
